package com.relayops.scheduling.domain;

/** Why an execution happened; stored on every run row. */
public enum TriggerSource {

    /** Fired by the scheduler. */
    SCHEDULE,

    /** Triggered by an operator from the admin page. */
    MANUAL,

    /** Replay of a missed occurrence. */
    CATCH_UP,

    /** Retry after a failure. */
    RETRY,

    /** Compensation for a holiday, generated by the application. */
    HOLIDAY_SHIFT
}
